 BananaEngine.Result run(Context c,Semilla m,String q)throws Exception{return BananaEngine.run(c,q,new ArrayList<String[]>(),"",true,m);}
 @Override public void onStart(){Bundle report=new Bundle();try{Context c=getTargetContext();RuntimeModules.prefs(c).edit().clear().commit();c.getSharedPreferences("shared-scene",0).edit().clear().commit();Semilla m=OwnBrain.load(c);run(c,m,"crea a Fito un zorro; agrega una banana llamada Bani");BananaEngine.Result automatic=run(c,m,"Fito le da un besito a Bani");check(automatic.changed&&RuntimeModules.revision(c)==1,"ordinary request auto-repair");note("NATIVE_AUTOMATIC_GAP_REPAIR_OK");RuntimeModules.prefs(c).edit().clear().commit();c.getSharedPreferences("shared-scene",0).edit().clear().commit();run(c,m,"crea a Fito un zorro; agrega una banana llamada Bani");run(c,m,"prepara ejemplo de modulo");run(c,m,"activa modulos");BananaEngine.Result out=run(c,m,"Fito celebra con Bani");check(out.changed&&out.scene.actions.get(0).equals("baila")&&RuntimeModules.revision(c)==1,"factory module active");JSONObject edited=new JSONObject(RuntimeModules.code(c));JSONObject module=edited.getJSONArray("modules").getJSONObject(0);module.getJSONArray("steps").getJSONObject(0).put("op","salta");module.getJSONArray("tests").getJSONObject(0).getJSONArray("actions").put(0,"salta");RuntimeModules.stage(c,edited.toString(),1);RuntimeModules.activate(c);int at=SceneStore.load(c).actions.size();out=run(c,m,"Fito celebra con Bani");check(out.changed&&out.scene.actions.get(at).equals("salta")&&RuntimeModules.revision(c)==2,"actual edited code changes request without APK rebuild");RuntimeModules.rollback(c);at=SceneStore.load(c).actions.size();out=run(c,m,"Fito celebra con Bani");check(out.changed&&out.scene.actions.get(at).equals("baila")&&RuntimeModules.revision(c)==3,"rollback restores actual behavior");note("NATIVE_CODE_EDIT_ACTIVATION_AND_ROLLBACK_OK");out=run(c,m,"repara este pedido: Fito le de un besito a Bani");check(out.changed&&out.scene.actions.contains("besa")&&RuntimeModules.revision(c)==4,"automatic repair writes tests activates and retries");JSONObject bad=new JSONObject(RuntimeModules.code(c));bad.getJSONArray("modules").getJSONObject(0).getJSONArray("tests").getJSONObject(0).getJSONArray("actions").put(0,"gira");RuntimeModules.stage(c,bad.toString(),4);try{RuntimeModules.activate(c);throw new AssertionError("failed test was activated");}catch(IllegalArgumentException expected){}check(RuntimeModules.revision(c)==4,"negative test preserves revision");note("NATIVE_LOCAL_REPAIR_AND_FAILED_TEST_GUARD_OK");report.putString("stream","PASS STAGE42 Android: real source edit changes interpreter output, automatic tests, hot activation, rollback, local repair/retry and failed-test isolation. No APK rebuild between module changes.\n");finish(Activity.RESULT_OK,report);}catch(Throwable e){StringWriter s=new StringWriter();e.printStackTrace(new PrintWriter(s));report.putString("stream","FAIL "+s);finish(Activity.RESULT_CANCELED,report);}}
